body:
This does work if I initialize the `special` schema with a provider that returns `general` schema, like this:

```c++
class GeneralProvider : public IRemoteSchemaDocumentProvider
{
public:
    GeneralProvider(const Document& generalDocument): _general(generalDocument) {}

    const SchemaDocument* GetRemoteDocument(const char* uri, SizeType length) {
        return &_general;
    }
private:
    SchemaDocument _general;
};

class DefinitionsProvider : public IRemoteSchemaDocumentProvider
{
public:
    DefinitionsProvider(const Document& generalDocument, const Document& specialDocument): _general(generalDocument), _special(specialDocument, 0, 0, &_general) {}
    const SchemaDocument* GetRemoteDocument(const char* uri, SizeType length) {
        return &_special;
    }
private:
    GeneralProvider _general;
    SchemaDocument _special;
};
```

But I expected it to automatically recognize the relationships between schemas in the context of the common provider.

Looks like `special` schema without explicit provider doesn't follow references to the `general`.
